/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input  logic clk,
    input  logic w,
    input  logic R,
    input  logic E,
    input  logic L,
    output logic Q
);
    always_ff @(posedge clk) begin
        if (L)
            Q <= R;
        else if (E)
            Q <= w;
    end
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'EOF'
"'`timescale 1ns/1ps
module dev_tb;
    logic clk = 0;
    logic w = 0, R = 0, E = 0, L = 0;
    wire Q;
    logic expected;
    integer checks = 0;
    TopModule dut (.clk(clk), .w(w), .R(R), .E(E), .L(L), .Q(Q));

    task automatic check_q(input logic value);
        if (Q !== value)
            $fatal(1, "FAIL check %0d: Q=%b expected=%b", checks, Q, value);
        checks = checks + 1;
    endtask

    task automatic cycle(input logic l_in, e_in, r_in, w_in);
        L = l_in; E = e_in; R = r_in; w = w_in;
        #2;
        check_q(expected);
        case ({l_in, e_in})
            2'"'b00: expected = expected;
            2'b01: expected = w_in;
            2'b10, 2'b11: expected = r_in;
        endcase
        clk = 1;
        #1;
        check_q(expected);
        clk = 0;
        #1;
        check_q(expected);
    endtask

    initial begin
        // Establish known state solely through the specified synchronous load.
        L = 1; R = 0;
        #2; clk = 1; #1;
        expected = 0;
        check_q(expected);
        clk = 0; #1;
        for (integer prior = 0; prior < 2; prior = prior + 1) begin
            for (integer inputs = 0; inputs < 16; inputs = inputs + 1) begin
                cycle(1, 0, prior[0], 0);
                cycle(inputs[3], inputs[2], inputs[1], inputs[0]);
            end
        end
        // Hold while unused data changes, then shift and load repeatedly.
        for (integer i = 0; i < 8; i = i + 1) begin
            cycle(0, 0, i[0], ~i[0]);
            cycle(0, 1, ~i[0], i[0]);
            cycle(1, 1, ~i[0], i[0]);
        end
        "'$display("PASS: %0d state/timing checks", checks);
        $finish;
    end
    initial begin
        #1000;
        $fatal(1, "FAIL: simulation watchdog timeout");
    end
endmodule
EOF
timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim.vvp candidate.sv dev_tb.sv > development_compile.log 2>&1
compile_status=$?
printf '"'%s\\n' \""'$compile_status" > development_compile.exit
if [ "$compile_status" -eq 0 ]; then
 timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/vvp dev_sim.vvp > development_simulation.log 2>&1
 printf '"'%s\\n' \""'$?" > development_simulation.exit
fi
cat development_compile.log development_simulation.log'

